var e={"profile.title":`ニックネーム`,"profile.desc":`Web のメッセージを Telegram にコピーするときに使われます（セッション内のメッセージの下には表示されません）。`,"profile.name":`名前`,"profile.nameDesc":`32文字まで。空欄の場合はニックネームなし。`,"profile.namePlaceholder":`例：Alex`,"profile.photo":`写真`,"profile.photoDesc":`色と絵文字の代わりに、ここやチームの連絡先に表示されます。このサーバーに保存されます。`,"profile.photoError":`この画像はここでは読み込めません。JPEG または PNG をお試しください。`,"profile.photoAdd":`写真を追加`,"profile.photoChange":`変更`,"profile.photoRemove":`削除`,"profile.color":`色`,"profile.colorDesc":`バッジの色です（写真がない場合）。`,"profile.emoji":`絵文字`,"profile.emojiDesc":`イニシャルの代わりにバッジに表示されます（任意、写真がない場合）。`,"profile.preview":`プレビュー`,"profile.previewText":`こんにちは！いつでも始められます。`,"profile.you":`あなた`,"register.desc":`すべて任意です。このサーバーが Harness Maxxing の作者に送る内容と、停止する方法です。`,"register.email":`メールアドレス（任意）`,"register.emailPlaceholder":`you@example.com`,"register.emailDesc":`セキュリティ上の問題や重要な変更をお知らせする場合にのみ使用します。共有や販売は一切しません。`,"register.emailInvalid":`メールアドレスの形式が正しくありません。`,"register.news":`新機能のお知らせも受け取る`,"register.newsDesc":`新機能について、多くても月に数回お送りします。配信はここからいつでも停止できます。`,"register.count":`インストール数のカウントに協力する（匿名）`,"register.countDesc":`1日1回、ランダムな番号、バージョン、システム（例：Ubuntu 24.04、x86_64）、いくつかのヘルスコード（サービスの稼働、Claude のログイン状態、前回の更新の失敗など）を送信します。名前、メールアドレス、IP、サーバー名、内容は含まれません。`,"register.countBlocked":`このサーバーでは、サービス環境の MAXXING_NO_TELEMETRY または DO_NOT_TRACK によってオフになっています。`,"register.privacy":`api.harness-maxxing.com に送信されます。ニックネームと言語はメールアドレスと一緒にのみ送られます。すべてのチェックを外すと送信は完全に止まり、このサーバーには二度と連絡しません。`,"register.statusOff":`このサーバーは作者に何も送信しません。`,"register.statusOn":`登録済みです。1日1回シグナルを送信します。`,"register.statusPending":`まだ送信されていません。次回の日次シグナルで送信されます。`,"register.statusError":`作者に接続できませんでした：{error}。明日もう一度試行します。`,"register.stop":`停止して連絡を受け取らない`,"license.title":`Enterprise ライセンス（任意）`,"license.desc":`Harness Maxxing は、個人での利用や、組織が自社の用途で使う場合は無料です。キーが必要なのは必要とする企業のみで、動作には影響しません。`,"license.read":`ライセンスを読む`,"license.whoTitle":`キーが必要な人は？`,"license.who1":`子会社、グループ会社、または顧客のために使用する組織。`,"license.who2":`再販、ホスティング、有償のインストールやサポートなど、これを含む有償サービス。`,"license.whoNot":`それ以外の方は不要です。個人、フリーランス、自社用途の組織は何もする必要はありません。`,"license.get":`Enterprise ライセンスを申請する`,"license.key":`ライセンスキー`,"license.keyDesc":`harness-maxxing.com で確認されます（1キー＝1サーバー）。ほかは何も変わらず、アップデートはこれまでどおり GitHub から提供されます。`,"license.invalid":`キーの形式は HM-XXXX-XXXX-XXXX-XXXX です。`,"license.save":`キーを保存`,"license.none":`キーは登録されていません。上記のケースに当てはまらなければ、これが通常の状態です。`,"license.active":`キー {key}（{kind}）`,"license.until":`{date} まで`,"license.remove":`キーを削除`,"license.removeDesc":`別のサーバーで使えるように枠を解放します。`,"license.onbToggle":`Enterprise ライセンスキーを持っています`,"license.onbToggleDesc":`任意です。キーをお持ちの企業のみ対象です。後から設定 -> 概要で変更できます。`,"tint.neutral":`ニュートラル`,"tint.tinted":`アクセント色`,"fonts.group.modern":`モダン`,"fonts.group.character":`個性的`,"fonts.group.rounded":`丸ゴシック`,"fonts.group.serif":`セリフ`,"fonts.group.readable":`読みやすい`,"fonts.group.mono":`等幅`,"fonts.group.system":`このデバイス`,"density.comfortable":`ゆったり`,"density.compact":`コンパクト`,"accent.clay":`オレンジ`,"accent.blue":`ブルー`,"accent.violet":`パープル`,"accent.green":`グリーン`,"accent.amber":`イエロー`,"accent.rose":`レッド`,"system.address":`アドレスとファイル`,"security.change":`パスワードを変更`,"security.changeDesc":`パスワードを変更すると、他のすべてのデバイスがログアウトされます。`,"security.current":`現在のパスワード`,"security.currentRequired":`現在のパスワードを入力してください。`,"security.currentWrong":`現在のパスワードが正しくありません。`,"security.update":`パスワードを更新`,"security.changed":`パスワードを変更しました`,"security.changedDesc":`他のデバイスはログアウトされました。`,"security.sessions":`ログイン中のデバイス`,"security.sessionsDesc":`ログインアラートを Telegram に送信できます（設定 › Telegram）。`,"security.status":`保護機能`,"security.statusDesc":`このサーバーを守っている機能と、まだ有効にしていないものです。`,"security.everywhere":`すべての場所からログアウトするには、パスワードを変更してください。既存のセッションクッキーはすべて直ちに無効になります。`,"security.app":`認証アプリ`,"security.appDesc":`パスワードの後、新しいブラウザではアプリ（Aegis、2FAS、Google Authenticator など）の6桁のコードが求められます。Telegram なしでも使えます。両方を有効にした場合は、どちらでもログインできます。UI を使わない緊急手段：サーバーで maxxing 2fa off を実行してください。`,"security.appOn":`認証アプリは有効です。`,"security.appOff":`認証アプリは無効です。`,"security.appPwDesc":`開始するには、現在のパスワードを入力してください。`,"security.appScan":`このコードをアプリでスキャンするか、キーを手動で入力し、アプリに表示される6桁のコードを入力してください。このコードが承認されるまで、何も変更されません。`,"security.appOpen":`このデバイスのアプリで開く`,"security.appKey":`キー`,"security.appCode":`6桁のコード`,"security.appBadCode":`コードが正しくありません。`,"security.appContinue":`続ける`,"security.appTurnOn":`有効にする`,"security.appOffTitle":`認証アプリを無効にする`,"security.appOffDesc":`現在のパスワードと、アプリのコード（またはリカバリーコード）を入力してください。`,"security.appOffCode":`アプリのコードまたはリカバリーコード`,"security.recovery":`リカバリーコード`,"security.recoveryDesc":`残り {n} 個。Telegram やアプリが使えないときに、各コードで2段階目のコードを1回分代用できます。`,"security.recoveryNew":`新しいコード`,"security.recoveryNewDesc":`現在のパスワードを入力してください。これまでのコードは使えなくなります。`,"security.recoveryTitle":`リカバリーコード`,"security.recoverySave":`安全な場所に保管してください。表示は1回だけです。各コードは1回のみ使えます。古いコードは使えなくなります。`,"security.recoverySaved":`保存しました`,"security.brThis":`このブラウザ`,"security.brSeen":`最終確認 {when}`,"security.brDisconnect":`ログアウト`,"security.brOthers":`他のすべてをログアウト`,"security.brOthersDone":`他のすべてのブラウザをログアウトしました。`,"security.brLegacy":`このバージョン以前にログインしたブラウザ`,"security.brLegacyDesc":`個別の行はありません。「他のすべてをログアウト」でログアウトされます。`,"cdef.defaultModel":`デフォルトモデル`,"cdef.cliDefault":`Claude Code のデフォルト`,"cdef.defaultModelHint":`セッションには、各ターンで実際に応答したモデルが表示されます。`,"cdef.autoCompact":`自動コンパクト`,"cdef.autoCompactHint":`ターン終了時のコンテキストがこのしきい値を超えると、Harness はセッションを要約し、その要約から始まる新しいスレッドで続行します（コンパクトと同様）。長いセッションが履歴全体を再送信しなくなるため、トークンを節約できます。履歴は表示されたままです。`,"cdef.autoCompactOff":`オフ`,"cdef.autoCompactRecommended":`推奨`,"cdef.idleCompact":`戻ったときにコンパクト`,"cdef.idleCompactHint":`Claude のプロンプトキャッシュは数分間（最長1時間）しか保持されません。それより長く放置されたセッションに、このコンテキスト以上の状態で書き込むと、Harness はまずセッションを要約し、あなたのメッセージは要約から始まる新しいスレッドで実行されます。履歴はどのみち通常料金で再送信されるため、以降のターンのコストが大きく下がります。返信の前に要約ターンが1回（短い待ち時間）かかります。`,"cdef.smartResume":`スマート再開`,"cdef.smartResumeHint":`キャッシュが切れたセッション（上記参照）にこのコンテキスト以上の状態で戻ったとき、または5分以上経過して2倍のコンテキストがあるとき、Harness はまず、いま送信したメッセージのために Claude にセッションを要約させます。要約にはメッセージに必要なもの（ファイル、コマンド、値、進行中の計画）が正確に残り、メッセージはずっと軽量な新しいスレッドで実行されます。実際の再開で計測したところ、100k以上でトークンが38〜67％減り、通常の要約より詳細もよく保たれました。オフ＝上記のルールのみ。`,"cdef.protectSecrets":`シークレットを保護`,"cdef.protectSecretsHint":`Claude のツールは、権限モードに関係なく、サーバーのシークレット（secrets.json）と SSH キー（~/.ssh）の読み取りや編集を拒否します。Web ページやメールに隠された指示によって単純に読み取られることを防ぎます。ファイルを開くために書かれたスクリプトは止められません。外部から来るコンテンツには、そのトピックでより厳格な権限モードを使うことをおすすめします。`,"cdef.shortTitles":`短いセッションタイトル`,"cdef.shortTitlesHint":`新しいセッションは、最初のメッセージから数語で名前が付けられます（挨拶や「〜してくれますか」は除きます）。オフ：タイトルはメッセージの冒頭になります。セッション名を変更した場合は常にそちらが優先されます。`,"cdef.shortTitlesModel":`Claude が書くタイトル`,"cdef.shortTitlesModelHint":`最小のモデルが話題を名付けます（より的確なタイトル）。新しいセッションごとに1回の簡単な呼び出しがあり、Claude プランの利用量に含まれます。`,"cdef.autoUpdate":`Claude Code を自動更新`,"cdef.autoUpdateHint":`デフォルトではオフです。オンの場合：Claude Code の新しい安定版が公開されると（すでに数日間使われているもので、最新版そのものではありません）、10分間何も実行されていない状態（ターン、待機中のメッセージ、定期ジョブがない）になり次第サーバーがインストールし、起動しない場合は前のバージョンに戻します。6時間ごとに確認され、結果は通知に表示されます。`,"cdef.autoUpdateLast":`最終更新：{from} → {to}、{date}`,"cdef.autoUpdateFailed":`{to} への更新に失敗しました（{date}）`,"telegram.setup":`Telegram を設定`,"telegram.setupDesc":`所要時間は約2分です。スマートフォンまたはパソコンに Telegram アプリが必要です。`,"telegram.sub.bot":`ボット`,"telegram.sub.link":`連携`,"telegram.sub.threads":`スレッド`,"telegram.bf1":`Telegram で次を開きます：`,"telegram.bf2":`次のコマンドを送信します：`,"telegram.bf3":`表示名を選び、続けて「bot」で終わるユーザー名を選びます（例：acme_maxxing_bot）。`,"telegram.bf4":`BotFather が 123456789:AAH… のようなトークンを返します。コピーして下に貼り付けてください。`,"telegram.token":`ボットトークン`,"telegram.tokenHint":`このサーバーに保存されます。トークンを持つ人は誰でもボットを操作できます。`,"telegram.tokenRequired":`BotFather のトークンを貼り付けてください。`,"telegram.tokenInvalid":`Telegram がこのトークンを拒否しました。`,"telegram.verify":`トークンを確認`,"telegram.botOk":`ボットを確認しました`,"telegram.linkIntro":`次に Telegram アカウントを連携します。連携したチャットだけが Harness と会話できます。`,"telegram.link":`Telegram を連携`,"telegram.qr":`ボットを開くための QR コード`,"telegram.scan":`スマートフォンでスキャン`,"telegram.openAndStart":`ボットを開いて「開始」を押してください。連携が完了すると、このページは自動的に更新されます。`,"telegram.openTelegram":`Telegram で開く`,"telegram.waiting":`/start を待機中…`,"telegram.manualCode":`または、ボットに次のメッセージを送信してください：`,"telegram.chatLinked":`チャットを連携しました`,"telegram.simpleIntro":`追うチャットは1つだけです。メッセージを書くとセッションが始まり（ボットがどのトピックにするか尋ねます）、メッセージに返信するとそのセッションが続きます。アラートもここに届きます。代わりにセッションごとに1スレッドにするには、設定 › Telegram › モードを開いてください。`,"telegram.threadsIntro":`開いている各セッションに専用のスレッドが作られます（さらに定期ジョブとアラート用も）。セッションをアーカイブするとそのスレッドは消えます。新しいセッションを始めるには、メインのチャットに書き込んでください。`,"telegram.created":`{count} 件のスレッドを作成しました`,"telegram.created#one":`{count} 件のスレッドを作成しました`,"telegram.topicsOff":`このボットではスレッドが無効です`,"telegram.topicsOff1":`@BotFather を開いて /mybots を送信し、ボットを選びます。`,"telegram.topicsOff2":`Bot Settings › Threaded Mode › オンにします。`,"telegram.topicsOff3":`ここに戻って「再試行」を押してください。`,"telegram.noThreads":`まだスレッドはありません。`,"telegram.thread.general":`一般`,"telegram.thread.crons":`定期ジョブのレポート`,"telegram.thread.alerts":`アラート`,"telegram.thread.feed":`通知`,"telegram.status":`状態`,"telegram.gateway":`ゲートウェイ`,"telegram.running":`稼働中`,"telegram.stopped":`停止中`,"telegram.bot":`ボット`,"telegram.chat":`連携済みチャット`,"telegram.test":`テストメッセージを送信`,"telegram.testSent":`テストメッセージを送信しました`,"telegram.behaviour":`動作`,"telegram.mode":`モード`,"telegram.modeDesc":`Telegramチャットの構成方法です。Telegramオプションを持つエージェントは、どのモードでも専用のスレッドを使います。`,"telegram.mode.simple":`シンプル`,"telegram.mode.simple.desc":`追うチャットは1つだけ。アラートと、返信としてのセッションが表示されます。メッセージを書いてトピックを選び、メッセージに返信するとそのセッションを続けられます。`,"telegram.mode.threads":`セッションごとにスレッド`,"telegram.mode.threads.desc":`Web UIの開いているセッションごとに専用のスレッドが作られ、定期ジョブ、アラート、通知のスレッドも用意されます。`,"telegram.mode.mirror":`スレッド＋Web会話`,"telegram.mode.mirror.desc":`セッションごとに1つのスレッドを作り、Web UIで書いた内容とHarnessの回答も通知音なしで表示されます。`,"telegram.mode.needsThreads":`@BotFatherでボットのThreaded Modeをオンにしてください。それまでは、チャットはシンプルモードで動作します。`,"telegram.mode.recommended":`おすすめ`,"telegram.modeConfirm":`Telegramから{count}件のスレッドを削除しますか？`,"telegram.modeConfirm#one":`Telegramから{count}件のスレッドを削除しますか？`,"telegram.modeConfirmDesc":`セッションのスレッドと、定期ジョブ、アラート、通知のスレッドが、メッセージごとTelegramから削除されます。セッションはWeb UIに残り、エージェントのスレッドはそのまま残ります。`,"telegram.modeConfirmOk":`シンプルに切り替える`,"telegram.notifySystem":`サーバーアラート`,"telegram.notifySystemDesc":`サーバーの問題（ディスク、サービス、Claudeのサインイン、バックアップ、アップデート）を、既読ボタン付きで通知します。`,"telegram.agentThreads":`エージェントのスレッド`,"telegram.agentThreadsDesc":`Telegramオプションを持つエージェントは、結果を専用のスレッドに投稿します。`,"telegram.notifyCrons":`定期ジョブのレポート`,"telegram.notifyCronsDesc":`定期ジョブの結果を投稿します（ジョブごとの設定が適用され、失敗時は通知音が鳴ります）。`,"telegram.loginAlerts":`サインインアラート`,"telegram.loginAlertsDesc":`サインインのたびにメッセージを送り、パスワードを繰り返し間違えた場合は通知音付きでアラートを出します。`,"telegram.replyMode":`返信`,"telegram.replyModeDesc":`リアルタイムの進捗：Harness の作業中に更新される1つのステータスメッセージ（タスクリストと各ステップ）が、最後に要約へ折りたたまれます。または最終回答のみ。`,"telegram.reply.final":`最終回答`,"telegram.reply.progress":`リアルタイムの進捗`,"trash.title":`ゴミ箱`,"trash.desc":`削除されたファイル、トピック、プロジェクト、セッションです。元の場所に復元するか、完全に削除できます。{days}日以上前の項目は自動的に削除されます。`,"trash.kind.file":`ファイル`,"trash.kind.folder":`フォルダ`,"trash.kind.topic":`トピック`,"trash.kind.project":`プロジェクト`,"trash.kind.session":`セッション`,"trash.kind.previous_versions":`以前のバージョン`,"trash.sessions":`{count}件のセッション`,"trash.root":`ワークスペースのルート`,"trash.restore":`復元`,"trash.restored":`{path} に復元しました`,"trash.deleteForever":`完全に削除`,"trash.deleteConfirm":`「{name}」を完全に削除しますか？`,"trash.deleteDesc":`この操作は元に戻せません。`,"trash.empty":`ゴミ箱を空にする`,"trash.emptyConfirm":`ゴミ箱を空にしますか？`,"trash.emptied":`ゴミ箱を空にしました`,"trash.none":`ゴミ箱は空です`,"trash.noneDesc":`削除したファイル、トピック、セッションはここに入ります。`,"packs.title":`スタータープロジェクト`,"packs.desc":`仕事の種類に合わせた、すぐ使えるプロジェクトです。各トピックは業務をすでに把握しており（プレイブック）、最初のセッションでいくつか質問します。ダミーデータはありません。パックは何度でも追加できます。追加するたびに新しいプロジェクトになります（2つ目のストアなら ecommerce-2 など）。既存のものが上書きされることはありません。`,"packs.restore":`元に戻す`,"packs.restored":`{count}個のファイルを元に戻しました`,"packs.nothingMissing":`不足はありませんでした`,"packs.add":`追加`,"packs.added":`追加済み`,"packs.jobs":`無効状態で作成された定期ジョブ：{list}`,"packs.done":`{name} を追加しました（{count} トピック）`,"packs.doneMany":`{count} 件のプロジェクトを追加しました`,"packs.doneMany#one":`{count} 件のプロジェクトを追加しました`,"packs.all":`すべてインストール`,"packs.choose":`選択`,"packs.none":`なし`,"import.title":`他のエージェントからインポート`,"import.desc":`Hermes、Claude Code、OpenClaw、その他のエージェント：あなたについて知っていることをプロジェクトとトピックとして書き出し、そのzipをここにドロップします。既存のものは上書きされません。`,"import.agent":`現在のエージェント`,"import.agentFile":`エージェント`,"import.other":`その他`,"import.more":`その他のインポート`,"import.step1":`このプロンプトをコピーして、現在のエージェントに送信してください。プロジェクト、トピック、メモリ、スキルをまとめたzipが作成されます。`,"import.step2":`受け取ったzipをドロップするか、クリックして選択してください。インポート前に内容を確認できます。`,"import.drop":`ここに.zipをドロップするか、クリックして選択`,"import.reading":`zipを読み込み中…`,"import.projects":`プロジェクト`,"import.topics":`トピック`,"import.skills":`スキル`,"import.files":`ファイル · {size}`,"import.new":`新規`,"import.merge":`既存 - 統合`,"import.rootMemory":`プロフィールと設定（ワークスペースのメモリ）`,"import.aside":`Harness 用に保管`,"import.neverOverwrite":`既存のメモリファイルには「インポート済み」セクションが追加されます。その他の既存ファイルはそのまま残し、インポートしたコピーを隣に保存します。`,"import.secrets":`{count} 件のファイルを拒否しました：キーまたはトークンが含まれています`,"import.secretsHint":`キーは、メモリファイルではなく、設定 → キーに追加してください。`,"import.skipped":`{count} 件のファイルをスキップしました`,"import.apply":`インポート`,"import.done":`インポートしました：プロジェクト {projects} 件、トピック {topics} 件、ファイル {files} 件。`,"import.mergedInto":`既存のメモリファイル {count} 件に「インポート済み」セクションを追加しました。`,"import.finish":`Harness にインポートを仕上げてもらう`,"import.finishTitle":`インポートを完了`,"import.finishHint":`Harness がインポートしたメモリを整理し、タスクを作成し、定期ジョブを提案し、追加すべきキーを一覧にします。`,"import.finishing":`Harness がインポートを仕上げています（タスク、定期ジョブ、追加するキー）。セッションで確認できます。`,"import.copy":`プロンプトをコピー`,"import.copied":`コピーしました`,"import.skillsN":`スキル`,"trash.loadFailed":`ゴミ箱を読み込めませんでした`,"trash.loadFailedDesc":`接続やアクセス権限を確認してから、再試行してください。`,"telegram.threads":`スレッド`,"telegram.threadsDesc":`開いているセッションごとに1つ、自動的に同期されます。Telegram でスレッドを削除すると、そのセッションはアーカイブされます（何も失われません）。`,"telegram.threadDays":`スレッドの保持期間`,"telegram.threadDaysDesc":`これより長く放置された開いているセッションはスレッドを失います（Web UI には残り、次のメッセージで復活します）。`,"telegram.days":`{count} 日`,"telegram.threadDaysConfirm":`{count} 件のスレッドを削除しますか？`,"telegram.threadDaysConfirm#one":`{count} 件のスレッドを削除しますか？`,"telegram.threadDaysConfirmDesc":`これらのセッションは新しい上限より長く放置されています。スレッドとその中のメッセージは Telegram から削除されます。セッションは Web UI に残り、次のメッセージで新しいスレッドが作られます。`,"telegram.threadDaysConfirmOk":`スレッドを削除`,"telegram.thread.session":`セッション`,"telegram.sync":`スレッドを同期`,"telegram.unlink":`Telegram の連携を解除`,"telegram.unlinkDesc":`ボットトークン、連携したチャット、スレッドの情報を削除します。セッションは Web UI に残ります。`,"telegram.unlinkConfirm":`Telegram の連携を解除しますか？`,"telegram.twoStepPassword":`2段階認証が有効です。連携の解除、ボットの変更、別のチャットの連携を行うと、このチャットの認証が外れるため、現在のパスワードが必要です。`,"telegram.topicsOffDesc":`すべてメインのチャットで動作します。セッションごとにスレッドを使うには、ボットの Threaded Mode を有効にしてください：`,"telegram.topicsStillOff":`このボットではスレッドがまだ無効です。@BotFather で Threaded Mode を確認してください。`,"telegram.retry":`再試行`,"telegram.changeBot":`ボットを変更`,"telegram.changeBotHint":`別のボットのトークン、またはこのボットの新しいトークンを貼り付けてください。トークンが確認されるまで何も変更されません。別のボットの場合は、再度連携が必要です。`,"telegram.newLink":`新しいリンク`,"telegram.expiresIn":`有効期限まであと {time}`,"telegram.expired":`このリンクは期限切れです`,"telegram.expiredDesc":`リンクの有効期間は15分です。新しいリンクを作成して、Telegram で開いてください。`,"telegram.startEarly":`すでに Telegram で開始を押しましたか？今すぐこのリンクを開く（またはコードをスキャンする）と、コードが送信されます。`,"telegram.relink":`別のチャットを連携`,"telegram.relinkDesc":`使用する Telegram アカウントからこのリンクを開いてください。連携中のチャットが置き換わります（ボットは同じままです）。`,"telegram.newToken":`新しいボットトークン`,"telegram.tokenRejected":`Telegram がボットトークンを拒否しました`,"telegram.tokenRejectedDesc":`トークンが @BotFather で無効化または再発行されたため、ボットは何も受信できません。新しいトークンを貼り付けてください（同じボットなら、チャットとスレッドは保持されます）。`,"telegram.removeWebhook":`Webhook を削除`,"telegram.err.webhook_set":`このボットはメッセージを Webhook に送信しています。別のプログラムが使用中です`,"telegram.err.webhookHelp":`ここでボットを使うには Webhook を削除してください（他のプログラムはメッセージを受信できなくなります）。または @BotFather で専用のボットを作成してください。`,"telegram.err.conflict":`別のプログラム（n8n、Hermes、OpenClaw…）がすでにこのボットを使用しています。停止するか、@BotFather で専用のボットを作成してください。`,"telegram.err.webhook_check_failed":`別のプログラムがこのボットを使用しているか確認できませんでした。しばらくしてからもう一度お試しください。`,"telegram.err.unreachable":`Telegram に接続できませんでした。しばらくしてからもう一度お試しください。`,"telegram.pollErrorTitle":`メッセージの受信`,"telegram.syncErrorTitle":`スレッドの同期`,"telegram.lastPoll":`Telegram からの最後の応答`,"telegram.never":`なし`,"telegram.testProblems":`テストメッセージを送信しましたが、問題があります：`,"telegram.testNotSent":`テストメッセージは送信されませんでした：`,"backup.whyTitle":`バックアップの理由`,"backup.why":`メモリファイルは、Harness を長く役立てるための基盤です。このサーバーが失われても、バックアップがあればインストーラーが新しいサーバーに1分で復元できます。送信されるのはホワイトリストに載ったテキストファイルだけで、キーらしきものはシークレットスキャナーがブロックします。`,"backup.gh1":`fine-grained トークンを次のページで作成してください：`,"backup.gh2":`リポジトリへのアクセス：リポジトリを自動作成する場合は「All repositories」、それ以外はバックアップ用リポジトリのみを選択します。`,"backup.gh3":`権限：`,"backup.gh3b":`（後者はリポジトリを作成する場合のみ）。`,"backup.gh4":`トークンを生成してコピーし、下に貼り付けてください。`,"backup.repo":`リポジトリ`,"backup.repoHint":`owner/name の形式です。プライベートである必要があります。`,"backup.repoInvalid":`owner/name の形式で入力してください。`,"backup.token":`GitHub トークン`,"backup.tokenRequired":`GitHub トークンを貼り付けてください。`,"backup.create":`プライベートリポジトリを作成する`,"backup.createHint":`まだ存在しない場合です。Administration 権限が必要です。`,"backup.connect":`確認して保存`,"backup.configFailed":`GitHub にアクセスを拒否されました。`,"backup.notPrivate":`このリポジトリは公開されています。バックアップはプッシュを拒否します。`,"backup.connected":`バックアップリポジトリを接続しました`,"backup.private":`プライベート`,"backup.runFirst":`最初のバックアップを実行`,"backup.runNow":`今すぐバックアップ`,"backup.runOk":`バックアップが完了しました`,"backup.runOkDesc":`{files}個のファイル、コミット {commit}。`,"backup.runFailed":`バックアップに失敗しました`,"backup.repository":`リポジトリ`,"backup.repositoryDesc":`メモリの送信先です。`,"backup.settings":`スケジュールと内容`,"backup.schedule":`スケジュール`,"backup.scheduleHint":`Cron式（お使いのタイムゾーン）。`,"backup.scheduleInvalid":`Cron式が正しくありません。`,"backup.include":`対象ファイル`,"backup.includeHint":`グレーのパターンは常に含まれます。ワークスペースからの相対パスでglobを追加してください。`,"backup.always":`常に含む`,"backup.addGlob":`パターンを追加`,"backup.history":`履歴`,"backup.historyDesc":`復元すると、現在のファイルはまずゴミ箱に保存されます。`,"backup.noHistory":`バックアップはまだありません`,"backup.noHistoryDesc":`実行されるとここに表示されます。`,"backup.filesCount":`{count}件のファイル`,"backup.filesCount#one":`{count}件のファイル`,"backup.changedCount":`{count}件変更`,"backup.restore":`復元`,"backup.restoreTitle":`このバックアップを復元しますか？`,"backup.restoreDesc":`ホワイトリストのファイル、定期ジョブ、設定がこのバージョンに置き換えられます。現在のファイルはまずゴミ箱に移動されます。`,"backup.restored":`{count}件のファイルを復元しました`,"backup.restored#one":`{count}件のファイルを復元しました`,"backup.forget":`バックアップの接続を解除`,"backup.forgetDesc":`リポジトリとトークンを削除します。リポジトリ自体は削除されません。`,"backup.forgetConfirm":`バックアップの接続を解除しますか？`,"mcp.whatTitle":`MCPサーバーはClaudeに新しいツールを追加します`,"mcp.whatExplain":"「すべてのセッション」に追加したサーバーはどこでも使えます。トピックに追加したサーバーは、そのトピックのセッションでのみ使えます。シークレットは 設定 → キー に保管し、${KEY_NAME} の形で参照します。トピックでClaudeに「MCP …を接続して」と頼むこともできます。","mcp.servers":`MCPサーバー`,"mcp.autoTitle":`読み込み`,"mcp.auto":`セッションが必要としたときだけMCPサーバーを読み込む`,"mcp.autoHint":"読み込まれたサーバーは、メッセージごとにトークンを消費し、ターンの開始を遅くします。オンにすると、セッションにはそのトピックで既に使われたサーバー、メッセージ内で名前を挙げたサーバー、トピックに追加されたサーバーが読み込まれます。Claudeは別のサーバーを要求でき（`maxxing mcp load`）、Harnessが自動的に続行します。claude.aiコネクタが必要な場合は、従来どおりすべてが読み込まれます。Harness Browserとデバイスのツールは、ターンで使う可能性があるときは常に利用できます。","mcp.serversDesc":`Claude Codeがこのワークスペースで読み込むサーバーです。`,"mcp.checkedAt":`状態の確認：{when}`,"mcp.check":`確認`,"mcp.checking":`確認中…`,"mcp.add":`サーバーを追加`,"mcp.addDesc":`アドレス（またはコマンド）はサービスのドキュメントに記載されています。`,"mcp.empty":`MCPサーバーがありません`,"mcp.emptyDesc":`ここで追加するか、必要なトピックでClaudeに頼んでください。`,"mcp.name":`名前`,"mcp.where":`適用先`,"mcp.whereHint":`すべてのセッション、または1つのトピックのセッションのみ。`,"mcp.searchTopic":`トピックを検索`,"mcp.everywhere":`すべてのセッション`,"mcp.stateCol":`状態`,"mcp.type":`種類`,"mcp.typeHttp":`アドレス（URL）`,"mcp.typeStdio":`ローカルプログラム`,"mcp.url":`アドレス`,"mcp.command":`コマンド`,"mcp.headers":`ヘッダー（任意）`,"mcp.env":`環境変数（任意）`,"mcp.addLine":`行を追加`,"mcp.insertKey":`保管庫のキーを挿入`,"mcp.noKeys":`設定 → キー にキーがありません`,"mcp.keysHint":"${KEY_NAME} の形で書かれたキーは、セッション開始時に保管庫から読み込まれます（セッションへは自動的に提供されます）。「接続」ボタンがあるサーバーにはキーは不要です。","mcp.literalWarn":"平文のトークンのようです。設定 → キー に保存し、${KEY_NAME} と書くことをおすすめします。","mcp.literal":`平文のトークン`,"mcp.nameInvalid":`使用できるのは英数字、「.」、「_」、「-」のみです。`,"mcp.urlInvalid":`アドレスは https:// で始めてください。`,"mcp.commandRequired":`サーバーを起動するコマンドを入力してください。`,"mcp.added":`{name}を追加しました`,"mcp.addedExposed":`{name}を追加しました - キーをセッションに渡すようになりました：{keys}`,"mcp.state.connected":`接続済み`,"mcp.state.needs_auth":`要接続`,"mcp.state.failed":`エラー`,"mcp.state.pending":`要承認`,"mcp.state.unknown":`未確認`,"mcp.connect":`接続`,"mcp.reconnect":`再接続`,"mcp.connectTitle":`{name} を接続`,"mcp.connectDesc":`最初の1回だけ、4つのステップで完了します。接続はすべてのセッションで保持されます。`,"mcp.preparing":`ログインページを準備しています…`,"mcp.step1":`サービスのログインページを開きます`,"mcp.openLogin":`ログインページを開く`,"mcp.step2":`{service} にログインして承認します`,"mcp.step3":`エラーページが表示されますが、正常です`,"mcp.step3Desc":`サービスから Harness サーバーのアドレス（「localhost」）に戻されますが、お使いのブラウザでは開けないため、「このサイトにアクセスできません」と表示されます。接続はまだ完了していません。コードはアドレスの中にあります。`,"mcp.browserError":`このサイトにアクセスできません - localhost に接続を拒否されました。`,"mcp.step3Copy":`アドレスバーからアドレス全体をコピーしてください（クリックして Ctrl+C / ⌘C）。スマートフォンの場合は、アドレスを長押ししてコピーします。`,"mcp.step4":`ここに戻って貼り付けます`,"mcp.paste":`貼り付け`,"mcp.pasteDenied":`ブラウザに拒否されました。入力欄で Ctrl+V / ⌘V を使って貼り付けてください。`,"mcp.noCode":`このアドレスには「code=」が含まれていません。承認後に表示されるエラーページのアドレスをコピーしてください。`,"mcp.whyTitle":`なぜコピーして貼り付けるのですか？`,"mcp.whyBody":`サーバー上で動作する Claude Code は、サーバーのローカルアドレスでサービスからの応答を待っています。サービスはブラウザをそのアドレスにしか戻せず、そのアドレスはサーバー上にしか存在しません。貼り付けることで、コードが Claude Code に渡され、接続が完了します。アクセス方法（ドメイン、Tailscale）にかかわらず動作し、ほかの操作は不要です。コードは期限切れになるため、数分以内に行ってください。`,"mcp.finish":`完了`,"mcp.retry":`再試行`,"mcp.connected":`{name} を接続しました`,"mcp.chatHint":`エージェントにはこの接続が必要です。完了したら、もう一度試すよう伝えてください。`,"mcp.chatConnected":`{name} は前回の確認時には接続済みでした。エージェントがまだ要求する場合は、再接続してください。`,"mcp.remove":`削除`,"mcp.removeTitle":`{name} を削除しますか？`,"mcp.removeDesc":`Claude はそこにあるツールを使えなくなります。保管庫のキーは保持されます。`,"keys.vault":`保管庫`,"keys.vaultDesc":`値は、表示しない限りサーバーの外に出ることはありません。`,"keys.add":`キーを追加`,"keys.edit":`キーを編集`,"keys.dialogDesc":`サーバーのシークレットファイルに保存されます（モード 600）。`,"keys.name":`名前`,"keys.nameHint":`環境変数の形式：OPENAI_API_KEY。`,"keys.nameInvalid":`英字で始まる、英字・数字・アンダースコアのみ使えます。`,"keys.value":`値`,"keys.valueKeep":`空のままにすると現在の値を保持します。`,"keys.valueRequired":`値を入力してください。`,"keys.exists":`この名前のキーはすでに存在します。「編集」から開いて変更してください。`,"keys.note":`メモ`,"keys.notePlaceholder":`用途や入手元`,"keys.noNote":`メモなし`,"keys.expose":`Harness のセッションに提供する`,"keys.exposeShort":`提供中`,"keys.unexpose":`提供を停止`,"keys.scope":`トピック：`,"keys.scopeAll":`すべて`,"keys.scopeCount":`{count} 件のトピック`,"keys.scopeCount#one":`{count} 件のトピック`,"keys.scopeChoose":`選択`,"keys.scopeClear":`すべて`,"keys.scopeEmpty":`プロジェクトはまだありません。`,"keys.scopeHint":`チェックを入れたプロジェクトとトピックのセッションと定期ジョブにのみ、このキーが渡されます。何もチェックしない場合は、すべてのトピックが対象です。エージェントは独自のキー一覧を保持します。`,"keys.exposeDesc":`Harness のターンごとに環境変数としてエクスポートされます。拡張機能はこの設定なしでもキーを読み取れるため、セッションで変数が必要な場合以外はオフのままにしてください。`,"keys.exposeTitle":`提供中のキー`,"keys.exposeExplain":`提供中のキーは、すべてのセッションと cron で環境変数（例：$OPENAI_API_KEY）として Harness から利用できます。値がプロンプトに現れることなく、スクリプトから使えます。ただし Harness はその値を読み取れるため、セッションに必要なものだけを提供してください。`,"keys.reveal":`表示`,"keys.copied":`{name} をコピーしました`,"keys.added":`キーを追加しました`,"keys.updated":`キーを更新しました`,"keys.deleteTitle":`{name} を削除しますか？`,"keys.deleteDesc":`このキーを使用しているスクリプトやセッションは動作しなくなります。`,"keys.empty":`キーはありません`,"keys.emptyDesc":`API キーやトークンは、ファイルではなくここに保管してください。`,"keyfiles.title":`ファイル`,"keyfiles.desc":`キーストア、サービスアカウントの JSON、証明書など。サーバー上に保管され、表示やダウンロードはできません。`,"keyfiles.add":`ファイルを追加`,"keyfiles.edit":`ファイルを編集`,"keyfiles.dialogDesc":`サーバー上の非公開フォルダに保存されます（モード 600）。最大 1 MiB。`,"keyfiles.nameHint":`環境変数の形式：ANDROID_KEYSTORE。キーと共有されます。1つの名前はキーかファイルのどちらかです。`,"keyfiles.file":`ファイル`,"keyfiles.fileHint":`任意の種類のファイル、最大 1 MiB。`,"keyfiles.fileKeep":`空のままにすると現在のファイル（{filename}）を保持します。`,"keyfiles.choose":`ファイルを選択`,"keyfiles.replace":`ファイルを置き換え`,"keyfiles.noneChosen":`ファイルが選択されていません`,"keyfiles.expose":`Harness のセッションにパスを提供する`,"keyfiles.exposeDesc":`環境変数 {name} に、ファイルの内容ではなくパスが入ります。すべての Harness セッションとシェルの cron ジョブで利用できます。`,"keyfiles.exposeTip":"${name} にファイルのパスが入ります","keyfiles.added":`ファイルを追加しました`,"keyfiles.updated":`ファイルを更新しました`,"keyfiles.deleteTitle":`{name} を削除しますか？`,"keyfiles.deleteDesc":`ファイルはサーバーから削除されます。このファイルを使用しているスクリプトやセッションは動作しなくなります。`,"keyfiles.empty":`ファイルはありません`,"keyfiles.emptyDesc":`キーストア、サービスアカウントの JSON、証明書は、プロジェクトのフォルダではなくここに保管してください。`,"keyfiles.safety":`安全な保管：ファイルはバックアップ、Git、メモリファイルの対象外で、このページから読み戻すこともできません。ただしセッションからの分離ではありません。セッションはサーバーと同じユーザーで動作するため、パスを渡されたセッションはファイルを読み取れます。`,"keyfiles.err.invalidName":`英大文字・数字・アンダースコアのみ使用できます。先頭は英字にしてください（2～64文字）。`,"keyfiles.err.reservedName":`この名前はシステムで予約されています。別の名前を選んでください。`,"keyfiles.err.nameTaken":`この名前はテキストキーですでに使われています。別の名前を選んでください。`,"keyfiles.err.nameTakenKey":`この名前はファイルですでに使われています。別の名前を選んでください。`,"keyfiles.err.exists":`この名前のファイルはすでに存在します。編集で開いて置き換えてください。`,"keyfiles.err.fileRequired":`ファイルを選んでください。`,"keyfiles.err.empty":`このファイルは空です。`,"keyfiles.err.tooLarge":`このファイルは大きすぎます。最大 1 MiB です。`,"keyfiles.err.invalidNote":`説明に保存できない文字（制御文字）が含まれています。削除してください。`,"keyfiles.err.unsupportedType":`サーバーがアップロード形式を受け付けませんでした。ページを再読み込みして、もう一度お試しください。`,"keyfiles.clear":`選択したファイルを外す`,"keyfiles.keepCurrent":`現在のファイルを保持`,"features.maxxing":`Maxxingモード（ベータ）`,"features.maxxingDesc":`セッションページに「⚡ Maxxing」スイッチ（Alt+M）を追加します。ブラウザごとにオンにします。セッションが終了すると、そのセッションだけが他の列の代わりに最前面に表示され、続きをすぐに入力できます。オフにすると、列が元に戻ります。`,"system.health":`状態`,"system.healthDesc":`30秒ごとに更新されます。`,"system.cpuPriorities":`CPU の優先度`,"system.cpuPrioritiesDesc":`プロセッサーが満杯のときは、見ているものが最優先になります。重い処理（レンダリング、定期ジョブ）は少し遅くなりますが、止まることはありません。`,"system.disk":`ディスク容量`,"system.diskDesc":`キャッシュ、古いバージョン、ログが使っている容量を解放します。プロジェクトとファイルには一切触れません。`,"system.diskUsed":`{total} 中 {used} 使用中 · 空き {free}`,"system.cleanup":`容量を解放`,"system.cleanupClaude":`Claude で整理`,"system.cleanupDesc":`自動で戻るものと、ご自身で選んだものだけが対象です。プロジェクト、添付ファイル、レンダリング結果は残ります。それらは「Claude で整理」で一緒に確認できます。`,"system.cleanupScanning":`計測中…`,"system.cleanupNothing":`解放するものはありません。すべてきれいな状態です。`,"system.cleanupRun":`{size} を解放`,"system.cleanupDone":`{size} を解放しました`,"system.cleanupFailed":`整理できなかった部分があります：{parts}`,"system.cleanup.leftovers":`古いバージョンと残りファイル`,"system.cleanup.leftoversDesc":`コンポーネントの以前のバージョン、使われなくなったブラウザー、一時ファイル、大きくなりすぎたログ。`,"system.cleanup.caches":`ダウンロードキャッシュ`,"system.cleanup.cachesDesc":`uv、npm、pip、npx のキャッシュ：次に必要になったときに再ダウンロードされます。実行中のツールが使っているものは残ります。`,"system.cleanup.journal":`システムログ`,"system.cleanup.journalDesc":`systemd のジャーナルを、直近の 200 MB まで縮小します。`,"system.cleanup.apt":`ダウンロード済みのシステムパッケージ`,"system.cleanup.aptDesc":`システムがインストール済みのパッケージ（apt、dnf、pacman のキャッシュ）。`,"system.cleanup.previews":`動画のプレビューとサムネイル`,"system.cleanup.previewsDesc":`プレーヤー用の軽量な動画コピーとファイルのサムネイル：表示時に再作成されます（多少の処理負荷があります）。過去30分以内に再生された動画は残ります。`,"system.cleanup.trash":`Harness のゴミ箱`,"system.cleanup.trashDesc":`削除したトピック、セッション、ファイル：後から復元できなくなります。`,"system.cleanupPrompt":"このサーバーのディスク容量を監査し、きちんと解放できるよう手伝ってください。\n\n1. 状態：`df -h` と `free -h`、続いて大きいフォルダー（`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`）を確認し、特に大きいものを掘り下げてください。設定 → システム → 容量を解放 では、ダウンロードキャッシュ、古いコンポーネントのバージョン、システムジャーナル、apt パッケージ、動画プレビュー、Harness のゴミ箱をすでに処理しているので、それらは除外してください。\n2. ワークスペースのすべてのプロジェクトとトピックを確認してください：添付ファイル、動画・音声のレンダリング結果、エクスポート、`node_modules`、Python 環境、ビルド、大きな git リポジトリ、忘れられた別コピー、重複ファイル。他のツールのキャッシュ（`~/.cache/*`、ダウンロード済みモデル）、ログ、`/tmp` 内の古いファイルも確認してください。\n3. 大きなものごとに、出所を突き止めてください：どのプロジェクト、ツール、定期ジョブが作成したのか（日付、内容、トピックのメモリ、cron）、まだ増え続けているかどうか。\n4. サイズ順の表を出してください：パス、サイズ、出所、自動で戻るかどうか、提案（削除、別の場所へ移動、保持）、解放できる容量。\n5. 私の了承なしに何も削除しないでください：質問はすべてまとめて聞いてください。何度も戻ってくるものについては、原因の修正（サイズ制限、それを生成するスクリプトやジョブ内での整理）を提案してください。\n6. 最後に、決まったこと（残すもの、整理するもの）を適切なトピックのメモリに書き留めてください。","system.claudeAuth":`Claude の認証`,"system.notConnected":`未接続`,"system.backupAge":`前回のバックアップ`,"system.never":`なし`,"system.hoursAgo":`{n} 時間前`,"system.failedLogins":`ログイン失敗（1時間）`,"system.load":`平均負荷`,"system.services":`サービス`,"system.servicesDesc":`Harness Maxxing に必要な systemd ユニット。`,"system.disabled":`無効`,"system.start":`開始`,"system.stop":`停止`,"system.restart":`再起動`,"system.stopTitle":`{name} を停止しますか？`,"system.restartTitle":`{name} を再起動しますか？`,"system.serviceConfirm":`このサービスが処理中の作業が中断されることがあります。`,"system.selfRestart":`画面は数秒間オフラインになり、自動的に再接続します。実行中の Harness のターンには影響しません。`,"system.actionDone":`{name}：完了`,"system.logs":`ログ`,"system.unit":`サービス`,"system.lines":`{n} 行`,"system.linesLabel":`行数`,"system.noLogs":`ログ行はありません。`,"system.logSearch":`行内を検索…`,"system.logLevelLabel":`レベル`,"system.logLevel.all":`すべての行`,"system.logLevel.warning":`警告とエラー`,"system.logLevel.error":`エラーのみ`,"system.logSinceLabel":`期間`,"system.logSince.all":`すべての期間`,"system.logSince.1h":`直近1時間`,"system.logSince.24h":`直近24時間`,"system.logSince.7d":`直近7日間`,"system.logMatched":`一致した{matched}行のうち、新しい{shown}行を表示しています。`,"system.logTruncated":`ログの新しい{n}行のみを読み込みました。より短い期間を選択してください。`,"system.metrics":`監視ツール用のメトリクス`,"system.metricsDesc":`すでにお使いの Prometheus、Grafana などの監視システム向けに、トークン、コスト、ターン、予算、定期ジョブ、サーバーの状態を1つのアドレスで提供します。使わない場合はオフのままにしてください。`,"system.metricsOn":`/metrics を公開`,"system.metricsOnDesc":`秘密のトークンがある場合のみ読み取れます。セッションのタイトル、メッセージ、ファイルは含まれません。`,"system.metricsTokenOnce":`トークンは今回だけ表示されます。今すぐ監視ツールに設定してください（Authorization: Bearer …）。`,"system.metricsTokenHint":`トークンは作成時に表示されました。紛失した場合は新しく作成してください。古いトークンは使えなくなります。`,"system.metricsNewToken":`新しいトークン`,"system.metricsNewTokenConfirm":`現在のトークンはすぐに使えなくなります。監視ツールには新しいトークンが必要です。`,"system.version":`バージョン`,"system.upToDate":`最新です`,"system.behind":`{n} 件の更新があります`,"system.unknownLatest":`最新バージョン不明`,"system.unknownLatestDesc":"更新用トークンで GitHub に接続できませんでした。サーバーで `maxxing update --check` を実行して原因（トークンの期限切れ、ネットワークなし）を確認してください。","system.check":`今すぐ確認`,"system.checkFailed":`確認に失敗しました`,"system.checkedAt":`確認：{when}`,"system.update":`今すぐ更新`,"system.updateTitle":`Harness Maxxing を更新しますか？`,"system.updateDesc":`新しいバージョンをダウンロードし、依存関係をインストールして、サービスを再起動します（約1分）。データ、ワークスペース、拡張機能はそのまま保持されます。`,"system.updating":`更新中…`,"system.restarting":`サーバーを再起動中…`,"system.updated":`更新をインストールしました`,"system.autoUpdate":`誰もいないときに自動で更新`,"system.autoUpdateHint":`初期設定ではオフです。オンにすると、新しいバージョンが公開され、誰も画面を開いておらず、何も実行されておらず（ターン、ジョブともに、10分間何もない）、更新によってカスタマイズが影響を受けない場合に、Harness が自動で更新し、数秒間再起動します。それ以外の場合は待機し、通知でお知らせします。バージョンがワークスペースに求める変更（アップグレードノート）も、更新後にそこでお知らせします。`,"system.autoLast":`前回の確認 {when}：{what}`,"system.autoTried":`自動で開始した前回の更新：{version}、{when}。`,"system.autoRes.started":`更新を開始しました。`,"system.autoRes.up_to_date":`Harness は最新です。`,"system.autoRes.needs_review":`新しいバージョンにはご確認が必要です（カスタマイズ、またはコードの未保存の変更があります）。「今すぐ更新」ボタンを使ってください。`,"system.autoRes.pending":`以前の更新がご対応待ちです。それが解決するまで何も試行しません。`,"system.autoRes.not_on_branch":`コードはブランチではなく、意図的に指定されたコミットにあります。そのままにしておきます。`,"system.autoRes.unavailable":`新しいバージョンを読み取れませんでした（ネットワーク？）。30分以内に再試行します。`,"system.autoRes.tried_recently":`このバージョンは過去24時間以内にすでに試行されています。次回の試行は明日です。`,"system.autoRes.failed":`更新を開始できませんでした。次回の試行は明日です。または「今すぐ更新」ボタンを使ってください。`,"system.autoWhy.browser":`待機中：誰かが画面を開いています（開いたままのタブも含まれます）。`,"system.autoWhy.turn":`待機中：セッションが作業中です。`,"system.autoWhy.queue":`待機中：セッションでメッセージが待機しています。`,"system.autoWhy.aside":`待機中：補足の質問に回答中です。`,"system.autoWhy.cron":`待機中：定期ジョブが実行中です。`,"system.autoWhy.recent":`待機中：10分以内にセッションが作業していました。`,"system.autoWhy.update":`待機中：更新がすでに実行中です。`,"system.autoWhy.work":`待機中：何かが実行中です。`,"system.updatedDesc":`新しいバージョンを使うには、ページを再読み込みしてください。`,"system.customs":`製品コードのカスタマイズ {count} 件（更新のたびに引き継がれます）`,"system.customs#one":`製品コードのカスタマイズ {count} 件（更新のたびに引き継がれます）`,"system.license":`ライセンス {key}（{kind}）- {email}`,"system.licenseKind.paid":`有償`,"system.licenseKind.beta":`ベータ`,"system.licenseKind.gift":`ギフト`,"system.licenseKind.enterprise":`エンタープライズ`,"system.licenseUpdatesUntil":`{date}までアップデート可能`,"system.licenseUpdatesEnded":`アップデートは{date}に終了しました。このサーバーは現在のバージョンのまま動作し続けます`,"system.licenseUpdatesForever":`アップデート込み`,"system.licenseMoving":`GitHubからのアップデートへの切り替え待ちです：{error}。6時間ごとに再試行します。`,"system.movedToGit":`すべてのインストールと同様に、{date}からGitHub（stableブランチ）経由でアップデートしています。キー{key}は保持されています。`,"system.pendingConflict":`アップデート{version}はHarnessの対応待ちです`,"system.pendingConflictDesc":`カスタマイズが新バージョンと競合しています。何も変更されておらず、現在のバージョンが動作し続けます。Harnessがsystemプロジェクト（トピック harness）で調整できます。`,"system.pendingRolledBack":`アップデート{version}を元に戻しました`,"system.pendingRolledBackDesc":`新バージョンが起動しなかったため、以前のバージョンを自動的に復元しました。失われたものはありません。systemプロジェクト（トピック harness）でHarnessに調査を依頼してください。`,"system.askClaude":`Harnessに相談`,"features.agentPreview":`ホバーでプレビュー`,"features.agentPreviewDesc":`リスト内のエージェントにポインターを置くと、作業内容が表示されます。Space の概要表示では、カードにそのルームも表示されます。`,"push.title":`モバイル通知`,"push.desc":`アプリを閉じていても、このスマートフォンやパソコンで「Harness が完了しました」を受け取れます。通知にはセッションのタイトルと回答の冒頭のみが含まれ、お使いのサーバーから送信されます。`,"push.here":`このデバイスに通知`,"push.hereDesc":`ブラウザに許可を求め、このデバイスを登録します。その後、あなたのセッションでターンが完了するたびに、表示中のもの以外がここに通知されます。`,"push.feed":`通知フィードから`,"push.feedDesc":`登録済みのデバイスでも鳴るものです。OKを待っているリクエストは、通知に許可と拒否のボタンが付いて届きます（Androidとパソコン。iPhoneではタップすると開きます）。アラートは警告とエラーです。失敗した定期ジョブ、いつもと違う支出、停止したサイトなどが該当します。`,"push.feed.all":`リクエストとアラート`,"push.feed.asks":`リクエストのみ`,"push.feed.off":`なし`,"push.test":`テストを送信`,"push.testSent":`テストを送信しました。数秒で届くはずです。`,"push.testNone":`テストをどのデバイスにも送信できませんでした。`,"push.denied":`このサイトの通知はブロックされています。ブラウザの設定で許可してから、もう一度お試しください。`,"push.noWorker":`アプリはまだ通知の準備ができていません。ページを再読み込みして、もう一度お試しください。`,"push.unsupported":`このブラウザは、アプリを閉じている間は通知を受け取れません。Android では Chrome、パソコンでは Chrome、Edge、Firefox をお使いください（HTTPS が必要です）。`,"push.install":`iPhone と iPad では、まずアプリをホーム画面に追加し（共有 → ホーム画面に追加）、そこから開いてこの機能をオンにしてください。`,"push.device":`デバイス`,"push.thisOne":`このデバイス`,"push.remove":`このデバイスを削除`,"memory.title":`セカンドブレインの整理`,"memory.desc":`すべての memory.md を短く整った状態に保ちます。重複の統合、矛盾の解消、古い履歴の要約、セクションの並べ替えを行います。毎晩（ジョブ「Memory compaction」）と、必要なときに実行されます。`,"memory.cleanNow":`今すぐ整理`,"memory.limit":`ファイルごとの最大長`,"memory.limitDesc":`これより長い、または重い（10行で1 KB：100行 = 10 KB）ファイルは、収まるように圧縮・再構成されます（余裕を残すため約80 %）。メモリファイルは変更のたびに全体が Claude に再送されます。短いほどコストが下がり、セッションの要約も少なくなります。`,"memory.lines":`{count} 行`,"memory.noLimit":`制限なし`,"memory.daily":`夜間クリーンアップ`,"memory.dailyDesc":`「Memory compaction」ジョブはデフォルトで5:00に実行されます。実行時刻の変更や無効化は定期ジョブで行えます。`,"memory.openCrons":`定期ジョブを開く`,"memory.files":`メモリファイル`,"memory.filesDesc":`ワークスペース内のすべての memory.md。`,"memory.overCount":`{count} 個のファイルが {limit} 行または {size} を超えています - 「今すぐクリーンアップ」で修正できます。`,"memory.overCount#one":`1 個のファイルが {limit} 行または {size} を超えています - 「今すぐクリーンアップ」で修正できます。`,"memory.allUnder":`すべてのファイルが {limit} 行以下、{size} 以下です。`,"memory.none":`メモリファイルはまだありません`,"memory.file":`ファイル`,"memory.lineCount":`行数`,"memory.size":`サイズ`,"memory.modified":`最終更新`,"memory.review.title":`Harness が書き込んだ内容`,"memory.review.desc.auto":`Harness が自分で学んだ内容をメモリに書き込みます。エージェントの実行後と、セッションをもとに1日1回行われます。各行には由来が記され、「元に戻す」で取り消せます。書き込まれる行の末尾には必ず日付が付きます。`,"memory.review.desc.ask":`Harness が自分で学んだ内容です。エージェントの実行後と、セッションをもとに1日1回行われます。承認するまで何も書き込まれません。書き込まれる行の末尾には必ず日付が付きます。`,"memory.review.desc.off":`このサーバーではメモリのレビューがオフです。Harness が自分でメモリに書き込むことはありません。`,"memory.review.none":`書き込み済み・提案中の内容はまだありません`,"memory.review.waiting":`待機中`,"memory.review.skill":`スキルを作成しました：{name}`,"memory.review.skillRemove":`スキル {name} を削除しますか？`,"memory.review.session":`セッションを見る`,"memory.review.accept":`承認`,"memory.review.refuse":`拒否`,"memory.review.undo":`元に戻す`,"memory.review.did.accept":`メモリに書き込みました`,"memory.review.did.refuse":`拒否しました。今後は提案されません`,"memory.review.did.undo":`取り消しました`,"memory.review.notDone":`未実行`,"memory.started":`クリーンアップを開始しました`,"memory.startedDesc":`Harness が新しいセッションでメモリファイルを圧縮しています。`,"stats.budget":`今日の予算`,"stats.budgetDesc":`サーバー全体の1日あたりの上限額（ドル）です。Claude Code が各ターンで報告する料金で計算されます（サブスクリプションの場合は、同じターンを API キーで実行したときの料金）。`,"stats.budgetField":`1日あたりの予算（$）`,"stats.budgetFieldDesc":`0 = 予算なし。80 % で通知、上限に達するとアラートを表示します。その後、定期ジョブとエージェントは翌日まで待機します。ご自身のメッセージと「今すぐ実行」は引き続き実行されます。`,"stats.budgetToday":`今日`,"stats.budgetSpent":"${limit} 中 ${spent}","stats.budgetReached":`予算に達しました。定期ジョブとエージェントは翌日まで待機します。`,"stats.limitRetry":`使用制限の後に再開`,"stats.limitRetryDesc":`Claude プランの使用制限で停止した定期ジョブやエージェントの実行は、制限がリセットされると自動的に再開します（リセットが1日以上先の場合は再開しません）。`,"stats.limitRetryDelay":`リセット後の待機時間（秒）`,"stats.limitRetryDelayDesc":`リセット時刻からどれくらい後に再開するか、0〜3600 で指定します。`,"stats.alerts":`アラート`,"stats.alertsDesc":`支出がいつもの範囲を外れたときに通知します。何も停止しません。停止は予算の役割です。`,"stats.alertSpend":`いつもと違う日`,"stats.alertSpendDesc":`今日の費用が、通常の日（直近14日間の中央値）のこの倍数に達したときに通知します。サーバー全体またはエージェント単位で設定できます。`,"stats.alertSpendTimes":`{n}倍`,"stats.alertOff":`オフ`,"stats.alertTurn":`高額なターン（$）`,"stats.alertTurnDesc":`1回のターンの費用がこの金額以上になったときに通知します。0 = アラートなし。`,"stats.alertErrors":`失敗を繰り返すターン`,"stats.alertErrorsDesc":`1回のターンで8回以上のツール呼び出しが失敗し、かつその半数以上が失敗した場合です。`,"stats.quota":`Claude プランの使用状況`,"stats.quotaDesc":`Claude サブスクリプションの上限に対する使用量です（週間、およびプランに5時間枠がある場合はその枠）。`,"stats.quotaEnable":`プランの使用状況を表示`,"stats.quotaEnableDesc":`試験的機能：Anthropic の非公開エンドポイントから取得するため、使えなくなる可能性があります。ダッシュボードのウィジェットも追加されます。`,"stats.fiveHour":`現在の5時間枠`,"stats.plan":`プラン：Claude {plan}`,"stats.noFiveHour":`5時間枠はありません。Ultra プランには週間の上限のみがあります。`,"stats.sevenDay":`今週`,"stats.resets":`{at} にリセット`,"stats.stale":`最後に取得した値です（エンドポイントが先ほど応答しませんでした）。`,"stats.quotaUnavailable":`このログイン方法ではプランの使用状況を利用できません。`,"stats.reason.no_oauth_credentials":`プランの使用状況を読み取るには、このサーバーで Claude にログインしてください（設定 -> Claude）。`,"stats.reason.api_key":`プランの使用状況は Claude のサブスクリプションでのみ利用できます。このサーバーは API キーを使用しています。`,"stats.reason.rate_limited":`Anthropic は使用状況の取得頻度を制限しています - 次回の取得は {when} です。`,"stats.reason.http_401":`Claude のログインが拒否されました。再度ログインしてください（設定 -> Claude）。`,"stats.reason.other":`プランの使用状況を読み取れませんでした（{code}）。`,"stats.nextReading":`次回の取得は {when} です。`,"stats.tokens":`トークン`,"stats.tokensDesc":`アーカイブ済みセッションを含む、Harness のすべてのターンから集計しています。日別グラフはこのバージョンから開始されます。`,"stats.empty":`Harness のターンはまだありません`,"stats.total":`トークン`,"stats.turns":`{count} ターン`,"stats.turns#one":`1 ターン`,"stats.turnsCol":`ターン`,"stats.inOut":`入力 / 出力`,"stats.cache":`キャッシュ読み取り / 書き込み`,"stats.cacheHint":`低コストなコンテキストの再読み込み`,"stats.turnStart":`ターン開始（中央値）`,"stats.turnStartHint":`最初の応答まで {first} 秒 · 直近 {count} ターン`,"stats.perDay":`1日あたりのトークン（30日間）`,"stats.groupBy":`グループ化`,"stats.byProject":`プロジェクト`,"stats.byTopic":`トピック`,"stats.bySession":`セッション`,"stats.byAgent":`エージェント`,"stats.costCol":`コスト`,"stats.export":`この表をダウンロード（全行）：`,"stats.exportDays":`日別（CSV）`,"about.desc":`無料の fair source：誰にとっても同じコードです。`,"about.checkUpdates":`アップデートを確認`,"features.pagesDesc":`サイドバーのすべてのページを、表示順に並べています。任意のページはオフにできます。ページが非表示になるだけで、何も削除されません。`,"features.thisBrowser":`このブラウザ`,"features.tabs":`タブモード`,"features.tabsDesc":`画面に表示するセッションは1つで、開いているセッションはその上にタブで表示されます。オフにするとゾーンモードになり、セッションが並べて表示されます。セッションページの右上でも切り替えられます（Alt+T）。`,"features.inSidebar":`サイドバー内`,"features.badges":`バッジ`,"features.badgesDesc":`サイドバーの各ページの横に表示されるカウンターです。オフにすると、そのページには数字もドットも表示されません。カウントはページ上には残ります。カウント対象のいずれかがエラーの場合、バッジは赤になります。`,"features.badge.home":`未読の通知。`,"features.badge.sessions":`未読の回答があるセッションと、作業中のセッション。`,"features.badge.team":`未読のメッセージ。`,"features.badge.agents":`新しい結果と承認待ち。`,"features.alwaysOn":`常にオン`,"features.page.dashboard":`ホーム画面です。ウィジェット、今日のアクティビティ、対応が必要なものを表示します。`,"features.page.sessions":`Claude との会話を、プロジェクトとトピックごとに管理します。`,"features.page.files":`サーバーのファイルを、閲覧、表示、アップロード、ダウンロードできます。`,"features.page.agents":`トピック内で動き続けるヘルパーです。それぞれに役割とメモリがあり、手動、スケジュール、Webhook、Telegram から起動できます。1日の予算内で動作します。`,"features.page.tasks":`やることのボード（カンバン、週、カレンダー、リスト）です。Claude も読み取り・更新でき、ダッシュボードのウィジェットも付いています。`,"features.page.team":`自分の Harness を持つ人とチャットできます。メッセージ、グループ、投票、ファイルをサーバー間でやり取りします。`,"features.page.mail":`メールボックスをここで読み、検索し、整理できます。セッション内では Claude も利用できます。`,"features.page.infra":`すべてのサイト、データベース、バケット、ドメイン、サーバーを、状態と場所とともに表示します。`,"features.page.git":`サーバーと GitHub アカウントのリポジトリを、ブランチとコミットのグラフで表示します。`,"features.need.team":`インターネット上の https アドレスが必要です（ドメインモード）。`,"features.need.mail":`IMAP/SMTP のメールボックスが必要です（アプリパスワードを使った Gmail、OVH など）。`,"features.need.infra":`このサーバーはそのまま動作します。Cloudflare と Hostinger はキーが必要です：`,"features.need.git":`GitHub には次の場所に GITHUB_TOKEN キーが必要です：`,"keys.gitSuggest":`GitHub のキーが保管庫にあります。Git ページにリポジトリとそのグラフが表示されます。`,"keys.gitSuggestOn":`Git ページを表示`,"appearance.theme":`テーマ`,"appearance.themeDesc":`ウィジェットを含むインターフェース全体の外観です。色とフォントはすぐ下で設定します。`,"appearance.default":`デフォルト`,"appearance.solidDesc":`単色で、くっきりと落ち着いた見た目です。`,"appearance.glassDesc":`バー、メニュー、ダイアログがアクセントカラーの背景に透けて見えます。`,"appearance.options":`{name} のオプション`,"appearance.optionsDesc":`ダークかライトか、アクセントカラー、背景、フォントを選べます。`,"appearance.by":`作者：{name}`,"appearance.onSolid":`ソリッド上`,"appearance.onGlass":`ガラス上`,"appearance.installedDesc":`インストール済みのテーマです。`,"appearance.unusable":`使用できないテーマ：`,"appearance.moreThemes":`その他のテーマ：あなたのために作成したもの、または Community から取得したものを Harness がインストールします。`,"appearance.ask":`Harness に依頼`,"appearance.askPrompt":`Harness Maxxing の新しいテーマがほしいです（スキル maxxing-theme）。イメージは次のとおりです：`,"appearance.fixedMode":`このテーマはこのモードのみです。`,"appearance.ownAccent":`このテーマで固定されています。`,"appearance.css":`詳細 CSS`,"appearance.cssDesc":`このテーマの追加スタイルルールです。色とは異なり、アップデート後に表示が崩れることがあります。問題がある場合はここでオフにしてください。`,"appearance.cssStale":`オフになりました：アップデートでインターフェースが変わりました。Harness が確認してからオンに戻します。`,"appearance.cssVerify":`Harness に確認を依頼`,"appearance.cssVerifyPrompt":`私のテーマ {id} の詳細 CSS がアップデートによりオフになりました。現在のインターフェースに合わせて確認し（スキル maxxing-theme）、必要なら修正してから、オンに戻してください。`,"appearance.layout":`レイアウト`,"appearance.layoutDesc":`余白、スマートフォンまたはパソコン向けのレイアウト、スマートフォンでの最初の画面。`,"security.privacy":`プライバシー`,"security.privacyDesc":`プレゼンテーションモードは、画面共有中にデータを隠します（サイドバー下部の目のアイコン）。`,"about.version":`バージョン {version}`,"about.community":`コミュニティ`,"emoji.pick":`絵文字を選択`,"emoji.search":`絵文字を検索`,"emoji.none":`絵文字が見つかりません`,"emoji.clear":`絵文字を削除`,"about.contact":`連絡を取る`,"import.restore":`メモリのバックアップ`,"import.restoreDesc":`サーバーを移行する場合：以前のサーバーのバックアップを GitHub リポジトリから復元します。`,"import.agentDesc":`エージェントファイル（.md、Claude Code 形式）：エージェントページ -> 新規エージェント -> インポート。`,"skills.where.workspace":`ワークスペース`,"skills.where.user":`サーバー`,"skills.slashOnly":`/{name} でのみ使用`,"skills.open":`開く`,"skills.edit":`Claude で編集`,"skills.editPrompt":`スキル {name}（{path}）を変更してください：`,"skills.publish":`コミュニティに共有`,"skills.publishPrompt":`スキル {name}（{path}）を、https://harness-maxxing.com/community/publish.md に従って Harness Maxxing コミュニティ向けに準備してください。個人データ、パス、シークレットが含まれていないか確認し、何を送ればよいか教えてください。`,"skills.search":`スキルを検索`,"skills.mine":`あなたのスキル`,"skills.mineDesc":`~/.claude/skills（すべてのセッション）、ワークスペース、またはプロジェクトやトピック（そのセッションのみ）に保存されます。`,"skills.new":`新規スキル`,"skills.newPrompt":`次のことを行うスキルを（適切な .claude/skills フォルダに）作成してください：`,"skills.emptyShipped":"Harness に付属のスキルがこのサーバーにありません。`maxxing update` で再インストールされます。","skills.noMatch":`一致するスキルがありません。`,"skills.empty":`あなたのスキルはまだありません`,"skills.emptyDesc":`同じ種類のタスクを繰り返すときは、Claude にスキルの作成を頼んでください。`,"skills.shipped":`Harness 付属`,"skills.shippedDesc":`更新のたびに更新されます：読むために開くことはできますが、編集しないでください。`,"pkg.from":`{date} に {source} からインストール`,"pkg.on":`{date} にインストール`,"pkg.modified":`インストール後に変更されたファイル`,"pkg.section":`コミュニティ`,"pkg.sectionDesc":`他のユーザーが共有した拡張機能、テーマ、スキル。内容を読んでからインストールできます。`,"pkg.catalogue":`コミュニティカタログ`,"pkg.catalogueDesc":`このページを開いたときに harness-maxxing.com から読み込みます。各項目は、レビュー済みのコミットでダウンロードされます。`,"pkg.site":`ウェブサイト`,"pkg.tab.extension":`拡張機能`,"pkg.tab.theme":`テーマ`,"pkg.tab.skill":`スキル`,"pkg.type.widget":`ウィジェット`,"pkg.type.page":`ページ`,"pkg.type.view":`エージェントビュー`,"pkg.serverCode":`サーバーコード`,"pkg.details":`詳細`,"pkg.installed":`インストール済み`,"pkg.checkInstall":`確認してインストール`,"pkg.unreachable":`カタログに接続できません`,"pkg.empty":`まだ何もありません`,"pkg.emptyDesc":`この種類のものは、まだ誰も共有していません。`,"pkg.reportDesc":`このサーバーで行われる内容です。コミット {commit} を、何も実行せずに読み取っています。`,"pkg.runsServer":`このサーバーでコードを実行します`,"pkg.runsBrowser":`このサーバーではコードは実行されません`,"pkg.files":`{n} 個のファイル`,"pkg.notVerdict":`あくまで読解の補助であり、判定ではありません。スキャンは可能な範囲で行いますが、見落としが生じる場合があります。インストールするものについては、ご自身で責任を負っていただきます。`,"pkg.disclaimer":`掲載情報は他のユーザーが作成したものです。可能な限り一つひとつ確認とスキャンを行っていますが、見落としが生じる場合があります。インストールするものについてはご自身で責任を負っていただき、Harness Maxxing は掲載内容の動作について責任を負いません。`,"pkg.readIt":`赤字の注意点を読み、インストールすることに同意します。`,"pkg.install":`インストール`,"pkg.replace":`インストール済みのものを置き換える`,"pkg.done":`{name} をインストールしました`,"skills.community":`他のユーザーが共有しているスキル：`,"features.page.jarvis":`話しかけるだけで済む1つのアシスタントです。プロジェクトやトピックを作成し、セッションやエージェントに作業を任せ、その結果を受け取って会話を続けます。朝のブリーフと、毎晩整理されるメモリも備えています。`,"features.need.jarvis":`セッションだけの場合より Claude のプランを多く消費します。セッションから返ってくる回答ごとに Jarvis のターンが1回増え、さらに朝のブリーフと夜間パス（Sonnet、動きのない日はスキップ）があります。消費を抑えるには、設定でブリーフや夜間パスをオフにしてください。`};export{e as default};